\pard\fi0\li0\qj\ri0\sb195\sa0\itap0 \plain \f1\expndtw30\lang1041\fs24 Literatur\plain \f1\lang1041\fs24 : {\field{\*\fldinst HYPERLINK "hida://bezlit[2].8330/?u"}{\fldrslt \plain \f3\scaps\lang1033\fs24\chcbpat18 Fechter}}{\field{\*\fldinst HYPERLINK "hida://bezlit[2].8330/?u"}{\fldrslt \plain \f3\lang1033\fs24\chcbpat18  (1974)}}\plain \f3\lang1033\fs24 , S. 319 \emdash  {\field{\*\fldinst HYPERLINK "hida://bezlit[3].8330/?u"}{\fldrslt \plain \f1\scaps\lang1041\fs24\chcbpat18 Fechter}}{\field{\*\fldinst HYPERLINK "hida://bezlit[3].8330/?u"}{\fldrslt \plain \f1\lang1041\fs24\chcbpat18  (1976)}}\plain \f1\lang1041\fs24 , S.\plain \f3\lang1033\fs24  79 \emdash  {\field{\*\fldinst HYPERLINK "hida://bezlit[4].8330/?u"}{\fldrslt \plain \f1\scaps\lang1041\fs24\chcbpat18 Stauffacher}}\plain \f1\lang1041\fs24  (1982), S. 8/7-8/11\plain \f3\lang1033\fs24  \emdash  {\field{\*\fldinst HYPERLINK "hida://bezlit[5].8330/?u"}{\fldrslt \plain \f3\scaps\lang1033\fs24\chcbpat18 S\u246 \'f6ller}}\plain \f3\lang1033\fs24  (1987), S. 131-138 \emdash \plain \f1\lang1041\fs24  \plain \f3\lang1033\fs24\cf1 \u8218 \'82Handschriftencensus\rquote  {\field{\*\fldinst HYPERLINK "http://cgi-host.uni-marburg.de/~mrep/beschreibung.php?id=15781"}{\fldrslt \plain \f1\lang1041\fs24\chcbpat17\cf1 http://www.handschriftencensus.de/16057}}\plain \f1\lang1041\fs24  (\plain \f3\scaps\lang1033\fs24 J\plain \f3\scaps\lang1033\fs24 \u252 \'fc\plain \f3\scaps\lang1033\fs24 rgen Wolf/Bal\plain \f3\scaps\lang1033\fs24 \u225 \'e1\plain \f3\scaps\lang1033\fs24 zs J. Nemes\plain \f1\lang1041\fs24 , September 2009).}

